INSERT IGNORE INTO `app_settings` (`setting_key`, `setting_value`, `value_type`, `is_secret`, `description`) VALUES
  ('claims.number_format', 'SIN-{YYYY}-{SEQ:6}', 'string', 0, 'Claim case number format. Tokens: {YYYY} {YY} {MM} {SEQ:n}'),
  ('claims.description_min_chars', '20', 'number', 0, 'Shortest description a customer may submit'),
  ('claims.draft_abandon_hours', '48', 'number', 0, 'Hours without activity after which an unfinished claim is marked abandoned (never deleted). Until then the customer is offered to resume it'),
  ('claims.description_max_chars', '1500', 'number', 0, 'Longest description a customer may submit'),
  ('claims.card_number_mode', 'certificate', 'string', 0, 'Assistance card number: same as the certificate number, a separate number, or not accepted'),
  ('claims.card_number_pattern', NULL, 'string', 0, 'Pattern a separate card number must match (regular expression). Empty accepts any'),
  ('claims.validation_max_attempts', '3', 'number', 0, 'Failed validations allowed per WhatsApp number before it is locked out'),
  ('claims.validation_lockout_minutes', '30', 'number', 0, 'How long a lockout lasts, and the window failures are counted in'),
  ('claims.validation_max_per_policy', '5', 'number', 0, 'Failed validations against one policy, from any number, before that policy is locked out'),
  ('claims.expiry_rule', 'incident_date', 'string', 0, 'Judge whether a policy has expired at the incident date (recommended) or today'),
  ('claims.filing_window_days', NULL, 'number', 0, 'Days after cover ends that a claim may still be filed. Empty means no limit'),
  ('claims.unpaid_policies', 'allow_flag', 'string', 0, 'Claims against an unpaid policy: accept and flag, or refuse'),
  ('claims.uncovered_claim_type', 'flag', 'string', 0, 'Claim type the plan does not cover: accept and flag, or refuse'),
  ('claims.max_documents', '10', 'number', 0, 'Most documents one claim may carry'),
  ('claims.max_file_mb', '10', 'number', 0, 'Largest single file accepted, in megabytes'),
  ('claims.document_retention_days', NULL, 'number', 0, 'Days uploaded documents are kept after a claim is closed or abandoned. Empty keeps them'),
  ('claims.notification_emails', NULL, 'string', 0, 'Who is emailed when a claim is submitted, comma separated. Empty means dashboard only'),
  ('claims.urgent_keywords_fr', 'urgence, urgent, hôpital, hopital, hospitalisé, hospitalise, inconscient, coma, saigne, saignement, crise cardiaque, avc, réanimation, reanimation, ambulance, arrêté, arrete, prison, garde à vue, décès, deces', 'string', 0, 'French words that mark a claim urgent, comma separated'),
  ('claims.urgent_keywords_en', 'emergency, urgent, hospital, hospitalised, hospitalized, unconscious, coma, bleeding, heart attack, stroke, intensive care, ambulance, arrested, jail, prison, custody, died, death', 'string', 0, 'English words that mark a claim urgent, comma separated'),
  ('claims.consent_text_fr', NULL, 'string', 0, 'Declaration the customer accepts before submitting, French. Empty skips the step'),
